import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const API_URL = "http://localhost:5001/api/products";

const HomePage = ({ onAddToCart }) => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    fetch(API_URL)
      .then((res) => {
        if (!res.ok) throw new Error("Gagal mengambil produk");
        return res.json();
      })
      .then((data) => {
        setProducts(data);
        setError(null);
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="bg-gray-50 dark:bg-gray-900 min-h-screen transition-colors duration-[900ms] ease-in-out">
      {/* Banner */}
      <div className="relative bg-gradient-to-r from-blue-600 to-blue-400 dark:from-blue-900 dark:to-gray-800 text-white py-16 px-4 mb-12 rounded-b-3xl shadow-lg transition-colors duration-[900ms] ease-in-out">
        <div className="max-w-4xl mx-auto text-center">
          <h1 className="text-4xl md:text-5xl font-bold mb-4 drop-shadow">Selamat Datang di Online Shop!</h1>
          <p className="text-lg md:text-xl mb-6">Temukan berbagai produk terbaik dengan harga terjangkau dan pelayanan cepat.</p>
          <Link to="/shop" className="inline-block bg-white dark:bg-gray-900 text-blue-700 dark:text-blue-200 font-bold px-8 py-3 rounded-full shadow hover:bg-blue-50 dark:hover:bg-gray-800 transition-colors duration-[900ms] ease-in-out">Belanja Sekarang</Link>
        </div>
      </div>

      {/* Produk Unggulan */}
      <div className="max-w-7xl mx-auto px-4 py-8">
        <h2 className="text-2xl font-bold mb-6 text-blue-700 dark:text-blue-200 transition-colors duration-[900ms] ease-in-out">Produk Unggulan</h2>
        {loading && <div>Memuat produk...</div>}
        {error && <div className="text-red-500">{error}</div>}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-8">
          {products.slice(0, 8).map((product) => (
            <Link
              key={product.id}
              to={`/shop/${product.id}`}
              className="border dark:border-gray-700 rounded-lg shadow bg-white dark:bg-gray-800 p-4 flex flex-col cursor-pointer hover:shadow-lg hover:ring-2 hover:ring-blue-400 dark:hover:ring-blue-500 transition-all duration-[900ms] ease-in-out group"
              tabIndex={0}
              aria-label={`Lihat detail ${product.name}`}
            >
              <img src={product.image} alt={product.name} className="w-full h-48 object-contain rounded mb-3 bg-gray-100 dark:bg-gray-700 transition-colors duration-[900ms] ease-in-out group-hover:scale-105" />
              <div className="font-semibold text-lg mb-1 text-gray-900 dark:text-gray-100 transition-colors duration-[900ms] ease-in-out">{product.name}</div>
              <div className="text-blue-700 dark:text-blue-300 font-bold mb-2 transition-colors duration-[900ms] ease-in-out">Rp {product.price.toLocaleString('id-ID')}</div>
              <div className="text-gray-500 dark:text-gray-300 text-sm line-clamp-2 mb-3 transition-colors duration-[900ms] ease-in-out">{product.description}</div>
              <button
                onClick={(e) => { e.preventDefault(); onAddToCart(product, () => {}); }}
                className="mt-auto bg-blue-600 dark:bg-blue-700 text-white px-4 py-2 rounded font-bold hover:bg-blue-700 dark:hover:bg-blue-800 transition-colors duration-[900ms] ease-in-out"
              >
                + Keranjang
              </button>
            </Link>
          ))}
        </div>
      </div>

      {/* Testimoni */}
      <div className="max-w-4xl mx-auto px-4 py-12">
        <h2 className="text-xl font-bold mb-6 text-blue-700 dark:text-blue-200 transition-colors duration-[900ms] ease-in-out">Testimoni Pelanggan</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 transition-colors duration-[900ms] ease-in-out">
            <div className="font-bold text-blue-600 dark:text-blue-300 mb-2 transition-colors duration-[900ms] ease-in-out">⭐⭐⭐⭐⭐</div>
            <div className="text-gray-700 dark:text-gray-200 mb-2 transition-colors duration-[900ms] ease-in-out">Pelayanan sangat cepat dan ramah. Produk sesuai deskripsi!</div>
            <div className="text-sm text-gray-500 dark:text-gray-400 transition-colors duration-[900ms] ease-in-out">- Andi, Jakarta</div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 transition-colors duration-[900ms] ease-in-out">
            <div className="font-bold text-blue-600 dark:text-blue-300 mb-2 transition-colors duration-[900ms] ease-in-out">⭐⭐⭐⭐⭐</div>
            <div className="text-gray-700 dark:text-gray-200 mb-2 transition-colors duration-[900ms] ease-in-out">Belanja di sini selalu puas, harga murah dan banyak promo.</div>
            <div className="text-sm text-gray-500 dark:text-gray-400 transition-colors duration-[900ms] ease-in-out">- Siti, Bandung</div>
          </div>
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 transition-colors duration-[900ms] ease-in-out">
            <div className="font-bold text-blue-600 dark:text-blue-300 mb-2 transition-colors duration-[900ms] ease-in-out">⭐⭐⭐⭐⭐</div>
            <div className="text-gray-700 dark:text-gray-200 mb-2 transition-colors duration-[900ms] ease-in-out">Produk dikirim cepat, packing aman. Recommended!</div>
            <div className="text-sm text-gray-500 dark:text-gray-400 transition-colors duration-[900ms] ease-in-out">- Budi, Surabaya</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HomePage;
